// Dashboard v1 (tarea 4.3): valida el contrato v1, guarda el último estado de cada nodo
// y reparte los datos a los widgets. Se ejecuta con cada mensaje MQTT y cada segundo (tick).
// Salidas: 1 Temp A | 2 Hum A | 3 Info A | 4 Temp B | 5 Hum B | 6 Info B
//          7 Temp amb | 8 Hum amb | 9 Info amb | 10 Gráfica temperaturas | 11 Gráfica PM | 12 Estado y alertas
const ahora = Date.now();
const FLAMA_RETENCION_MS = 5000;                  // sin flame:true durante este tiempo, la alerta se limpia
const SIN_DATOS_MS = { rack: 10000, ambiente: 20000 };

const S = flow.get('mvp43') || {
    nodos: {}, rack: { A: null, B: null, errGlobal: [] }, amb: null,
    flama: { activa: false, ultima: 0 }, rechazados: 0, ultimoRechazo: ''
};
const salidas = new Array(12).fill(null);
const grafT = [];
const grafP = [];

const num = v => (typeof v === 'number' && isFinite(v)) ? v : null;
const fmt = (v, d, u) => num(v) === null ? '—' : v.toFixed(d) + (u ? ' ' + u : '');
const fmtRate = v => num(v) === null ? '—' : (v > 0 ? '+' : '') + v.toFixed(1) + ' °C/min';
const tipoDe = id => id.startsWith('rack') ? 'rack' : (id.startsWith('amb') ? 'ambiente' : 'otro');
function nodo(id) {
    if (!S.nodos[id]) S.nodos[id] = { id: id, tipo: tipoDe(id), estado: null, fw: null, seq: null, perdidos: 0, reinicios: 0, visto: 0 };
    return S.nodos[id];
}

// ---- 1) Validación del contrato v1 (misma lógica del flujo 4.1)
function validar(m, t) {
    const e = [];
    if (typeof m !== 'object' || m === null || Array.isArray(m)) return ['el contenido no es un objeto JSON'];
    if (m.schema !== 1) e.push('schema debe ser 1');
    if (typeof m.node_id !== 'string' || m.node_id === '') e.push('falta node_id');
    if (t === 'site/datos') {
        if (m.type !== 'rack' && m.type !== 'ambiente') e.push('type debe ser rack o ambiente');
        if (!Number.isInteger(m.seq)) e.push('falta seq entero');
        if (m.type === 'rack' && !Array.isArray(m.positions)) e.push('rack sin positions');
    } else if (typeof t === 'string' && t.startsWith('site/estado/')) {
        if (m.status !== 'online' && m.status !== 'offline') e.push('status debe ser online u offline');
        if (t !== 'site/estado/' + m.node_id) e.push('el tema no coincide con node_id');
    } else {
        e.push('tema no esperado: ' + t);
    }
    return e;
}

// ---- 2) Procesar el mensaje recibido
const t = msg.topic;
if (t !== 'tick') {
    const m = msg.payload;
    const errores = validar(m, t);
    if (errores.length) {
        S.rechazados++;
        S.ultimoRechazo = errores.join('; ');
    } else if (t === 'site/datos') {
        const n = nodo(m.node_id);
        n.tipo = m.type;
        if (n.estado === 'offline') n.estado = 'online';          // si llegan datos, el nodo está vivo
        if (n.seq !== null) {
            if (m.seq <= n.seq) n.reinicios++;
            else if (m.seq > n.seq + 1) n.perdidos += m.seq - n.seq - 1;
        }
        n.seq = m.seq;
        n.visto = ahora;

        if (m.type === 'rack') {
            S.rack.errGlobal = Array.isArray(m.err) ? m.err : [];
            for (const p of m.positions) {
                if (p.id !== 'A' && p.id !== 'B') continue;
                S.rack[p.id] = {
                    temp: num(p.temp), hum: num(p.hum), dew: num(p.dew_point), rate: num(p.rate_c_min),
                    err: Array.isArray(p.err) ? p.err : [], visto: ahora
                };
                const base = p.id === 'A' ? 0 : 3;
                if (num(p.temp) !== null) {
                    salidas[base] = { payload: p.temp };
                    grafT.push({ topic: 'Rack ' + p.id, payload: p.temp });
                }
                if (num(p.hum) !== null) salidas[base + 1] = { payload: p.hum };
                if (p.flame === true) { S.flama.activa = true; S.flama.ultima = ahora; }
                else if (p.flame === false) { S.flama.activa = false; }
            }
        } else {
            S.amb = {
                temp: num(m.temp), hum: num(m.hum), dew: num(m.dew_point), rate: num(m.rate_c_min),
                pm1: num(m.pm1_0), pm25: num(m.pm2_5), pm10: num(m.pm10),
                err: Array.isArray(m.err) ? m.err : [], visto: ahora
            };
            if (S.amb.temp !== null) { salidas[6] = { payload: S.amb.temp }; grafT.push({ topic: 'Ambiente', payload: S.amb.temp }); }
            if (S.amb.hum !== null) salidas[7] = { payload: S.amb.hum };
            if (S.amb.pm1 !== null) grafP.push({ topic: 'PM1.0', payload: S.amb.pm1 });
            if (S.amb.pm25 !== null) grafP.push({ topic: 'PM2.5', payload: S.amb.pm25 });
            if (S.amb.pm10 !== null) grafP.push({ topic: 'PM10', payload: S.amb.pm10 });
        }
    } else {
        const n = nodo(m.node_id);
        n.estado = m.status;
        if (m.fw) n.fw = m.fw;
    }
}

// La alerta de flama se limpia si pasan unos segundos sin flame:true
if (S.flama.activa && ahora - S.flama.ultima > FLAMA_RETENCION_MS) S.flama.activa = false;

// ---- 3) Estado de los nodos y alertas
function estadoNodo(n) {
    if (n.estado === 'offline') return { texto: 'Desconectado', nivel: 'mal' };
    if (!n.visto) return n.estado === 'online' ? { texto: 'En línea, sin datos aún', nivel: 'aviso' } : { texto: 'Sin información', nivel: 'nd' };
    if (ahora - n.visto > (SIN_DATOS_MS[n.tipo] || 20000)) return { texto: 'Sin datos', nivel: 'aviso' };
    return { texto: 'En línea', nivel: 'ok' };
}
const etiqueta = n => n.tipo === 'rack' ? 'Nodo rack' : (n.tipo === 'ambiente' ? 'Nodo ambiente' : n.id);
const edad = visto => visto ? Math.round((ahora - visto) / 1000) : null;

const alertas = [];
if (S.flama.activa) alertas.push({ nivel: 'critica', tipo: 'flama', texto: 'FLAMA detectada en el rack (posición A, arriba)' });
const listaNodos = Object.keys(S.nodos).sort().map(id => {
    const n = S.nodos[id];
    const e = estadoNodo(n);
    if (e.nivel === 'mal') alertas.push({ nivel: 'critica', tipo: 'offline', texto: etiqueta(n) + ' (' + n.id + ') desconectado' });
    if (e.nivel === 'aviso') alertas.push({ nivel: 'aviso', tipo: 'sindatos', texto: etiqueta(n) + ' (' + n.id + '): ' + e.texto.toLowerCase() });
    return { id: n.id, etiqueta: etiqueta(n), estado: e.texto, nivel: e.nivel, seq: n.seq, perdidos: n.perdidos, reinicios: n.reinicios, fw: n.fw, edad: edad(n.visto) };
});
const errRack = (S.rack.errGlobal || []).concat((S.rack.A ? S.rack.A.err : []), (S.rack.B ? S.rack.B.err : []));
errRack.forEach(c => alertas.push({ nivel: 'aviso', tipo: 'sensor', texto: 'Rack: ' + c }));
if (S.amb) S.amb.err.forEach(c => alertas.push({ nivel: 'aviso', tipo: 'sensor', texto: 'Ambiente: ' + c }));

// ---- 4) Paneles de información
function infoRack(id) {
    const p = S.rack[id];
    if (!p) return null;
    return {
        flame: id === 'A' ? S.flama.activa : null,
        filas: [['Punto de rocío', fmt(p.dew, 1, '°C')], ['Variación', fmtRate(p.rate)]],
        errores: p.err.concat(S.rack.errGlobal || []),
        edad: edad(p.visto)
    };
}
function infoAmb() {
    const a = S.amb;
    if (!a) return null;
    return {
        flame: null,
        filas: [['Punto de rocío', fmt(a.dew, 1, '°C')], ['Variación', fmtRate(a.rate)],
                ['PM1.0', fmt(a.pm1, 0, 'µg/m³')], ['PM2.5', fmt(a.pm25, 0, 'µg/m³')], ['PM10', fmt(a.pm10, 0, 'µg/m³')]],
        errores: a.err,
        edad: edad(a.visto)
    };
}
const iA = infoRack('A'), iB = infoRack('B'), iM = infoAmb();
if (iA) salidas[2] = { payload: iA };
if (iB) salidas[5] = { payload: iB };
if (iM) salidas[8] = { payload: iM };
if (grafT.length) salidas[9] = grafT;
if (grafP.length) salidas[10] = grafP;
salidas[11] = { payload: { alertas: alertas, nodos: listaNodos, rechazados: S.rechazados, ultimoRechazo: S.ultimoRechazo } };

flow.set('mvp43', S);
return salidas;
